import{_ as e,c as a,o as r,a1 as t,eD as n,eE as s}from"./chunks/framework.D7x6il7h.js";const u=JSON.parse('{"title":"Webbens historia","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/3-web/index.md","filePath":"web1/3-web/index.md"}'),l={name:"web1/3-web/index.md"},i=t('<h1 id="webbens-historia" tabindex="-1">Webbens historia <a class="header-anchor" href="#webbens-historia" aria-label="Permalink to &quot;Webbens historia&quot;">​</a></h1><p>Webben, eller World Wide Web, är något vi använder varje dag för att surfa, läsa nyheter, kolla sociala medier och mycket mer. Men hur började allt? Webbens historia är en berättelse om hur en enkel idé om att dela information mellan forskare växte till en global plattform som idag påverkar hela världen. Genom att förstå webbens utveckling kan vi också förstå hur den har format vårt samhälle och våra liv. I denna genomgång ska vi titta närmare på hur webben skapades, hur den utvecklades och vad den har lett till idag.</p><p align="center"><img src="'+n+'" alt="historia-bild"></p><h2 id="vad-ar-webben" tabindex="-1">Vad är webben? <a class="header-anchor" href="#vad-ar-webben" aria-label="Permalink to &quot;Vad är webben?&quot;">​</a></h2><p>För att förstå webbens historia är det viktigt att först förstå några grundläggande begrepp:</p><ul><li><span class="f">Internet</span>: Ett globalt nätverk av datorer som är kopplade till varandra. Internet är infrastrukturen som gör det möjligt för oss att använda webben.</li><li><span class="f">World Wide Web</span> (<span class="f">WWW</span>): En tjänst på internet som gör det möjligt att dela och visa information genom webbsidor. Webben är alltså en del av internet.</li><li><span class="f">Webbläsare</span>: Ett program, som Google Chrome eller Safari, som används för att besöka webbsidor.</li><li><span class="f">Hyperlänk</span>: En klickbar länk som kopplar ihop olika webbsidor och gör det enkelt att navigera på webben.</li></ul><h2 id="har-ar-en-enkel-tidslinje-over-hur-webben-utvecklades" tabindex="-1">Här är en enkel tidslinje över hur webben utvecklades <a class="header-anchor" href="#har-ar-en-enkel-tidslinje-over-hur-webben-utvecklades" aria-label="Permalink to &quot;Här är en enkel tidslinje över hur webben utvecklades&quot;">​</a></h2><p align="center"><img src="'+s+'" alt="historia-bild"></p><h3 id="_1-borjan-av-internet-1960-och-1970-talet" tabindex="-1">1. Början av internet (1960- och 1970-talet) <a class="header-anchor" href="#_1-borjan-av-internet-1960-och-1970-talet" aria-label="Permalink to &quot;1. Början av internet (1960- och 1970-talet)&quot;">​</a></h3><ul><li>Internet började som ett projekt under 1960-talet.</li><li>Det kallades <span class="f">ARPANET</span> och skapades av forskare i USA för att dela information mellan datorer.</li><li>Det var inte som dagens webbsidor – det var bara ett sätt att skicka meddelanden och filer mellan datorer.</li></ul><h3 id="_2-world-wide-web-fods-1989" tabindex="-1">2. World Wide Web föds (1989) <a class="header-anchor" href="#_2-world-wide-web-fods-1989" aria-label="Permalink to &quot;2. World Wide Web föds (1989)&quot;">​</a></h3><ul><li>År 1989 skapade en forskare vid namn <span class="f">Tim Berners-Lee</span> det vi idag kallar World Wide Web.</li><li>Han jobbade på <span class="f">CERN</span>, ett forskningscenter i Schweiz.</li><li>Han uppfann tre viktiga saker: <ul><li><span class="f">HTML</span> (<strong>HyperText Markup Language</strong>): Ett språk för att skapa webbsidor.</li><li><span class="f">HTTP</span> (<strong>HyperText Transfer Protocol</strong>): Ett sätt för datorer att kommunicera på webben.</li><li><span class="f">URL</span> (<strong>Uniform Resource Locator</strong>): Adresser för att hitta webbsidor, som t.ex. <a href="https://www.home.cern/science/computing/birth-web" target="_blank" rel="noreferrer">www.home.cern</a></li></ul></li></ul><h3 id="_3-forsta-webbsidan-1991" tabindex="-1">3. Första webbsidan (1991) <a class="header-anchor" href="#_3-forsta-webbsidan-1991" aria-label="Permalink to &quot;3. Första webbsidan (1991)&quot;">​</a></h3><ul><li>Den allra <span class="f"><a href="http://info.cern.ch/" target="_blank" rel="noreferrer">första webbsidan skapades 1991</a></span>.</li><li>Den var väldigt enkel och innehöll bara text och länkar.</li><li>Syftet var att förklara hur webben fungerade.</li></ul><h3 id="_4-webben-blir-popular-1990-talet" tabindex="-1">4. Webben blir populär (1990-talet) <a class="header-anchor" href="#_4-webben-blir-popular-1990-talet" aria-label="Permalink to &quot;4. Webben blir populär (1990-talet)&quot;">​</a></h3><ul><li>På <span class="f">1990-talet</span> började fler och fler använda webben.</li><li>Webbläsare som <span class="f">Mosaic</span> (<span class="f">1993</span>) och senare <span class="f">Netscape</span> gjorde det enkelt att surfa på webben.</li><li>Företag började också skapa webbsidor, och det blev möjligt att shoppa, läsa nyheter och hitta information online.</li></ul><h3 id="_5-sokmotorer-och-sociala-medier-2000-talet" tabindex="-1">5. Sökmotorer och sociala medier (2000-talet) <a class="header-anchor" href="#_5-sokmotorer-och-sociala-medier-2000-talet" aria-label="Permalink to &quot;5. Sökmotorer och sociala medier (2000-talet)&quot;">​</a></h3><ul><li>På 2000-talet blev webben ännu större.</li><li>Sökmotorer som <span class="f">Google</span> (startade 1998) gjorde det lätt att hitta information.</li><li>Sociala medier som <span class="f">Facebook</span> (2004), <span class="f">Twitter</span> (2006) och senare <span class="f">Instagram</span> och <span class="f">TikTok</span> förändrade hur vi kommunicerar.</li></ul><h3 id="_6-mobil-webbsurf-och-modern-tid" tabindex="-1">6. Mobil webbsurf och modern tid <a class="header-anchor" href="#_6-mobil-webbsurf-och-modern-tid" aria-label="Permalink to &quot;6. Mobil webbsurf och modern tid&quot;">​</a></h3><ul><li>Idag använder de flesta <span class="f">smartphones</span> för att surfa på webben.</li><li><span class="f">Appar</span> och <span class="f">responsiva webbsidor</span> gör det enkelt att använda webben var som helst.</li><li>Tekniker som <span class="f">AI</span> (artificiell intelligens) och <span class="f">molntjänster</span> gör webben ännu smartare och snabbare.</li></ul><br><p>Webben har utvecklats från ett enkelt verktyg för forskare till en global plattform som alla kan använda. Den gör det möjligt att lära sig, kommunicera och skapa på nya sätt. Framtiden för webben ser ljus ut med ny teknik som fortsätter att förändra världen.</p><br><p>😎 👊 👍</p>',24),o=[i];function b(d,c,h,p,f,m){return r(),a("div",null,o)}const w=e(l,[["render",b]]);export{u as __pageData,w as default};
